  'Settled on {date}: {amount} moved to 2210 VAT due to the Tax Authority.': 'تمت التسوية في {date}: نُقل {amount} إلى ٢٢١٠ ضريبة القيمة المضافة المستحقة لمصلحة الضرائب.',
  'Settled on {date}: {amount} credit kept in 2210.': 'تمت التسوية في {date}: رصيد دائن {amount} محفوظ في ٢٢١٠.',
  'Record the payment to the Authority with a journal voucher (debit 2210, credit the bank).': 'سجّل السداد لمصلحة الضرائب بقيد يومية (مدين ٢٢١٠، دائن البنك).',
  'Settle the VAT for {month}? Output and input VAT move to 2210 VAT due to the Tax Authority, dated {date}.': 'تسوية ضريبة القيمة المضافة لـ {month}؟ تنتقل ضريبة المخرجات والمدخلات إلى ٢٢١٠ الضريبة المستحقة لمصلحة الضرائب بتاريخ {date}.',
  'VAT for {month} settled': 'تمت تسوية ضريبة {month}',
  'Settle VAT for {month}': 'تسوية ضريبة {month}',
  'Close {month} first (Close the books tab), so its figures can’t change after you file.': 'أقفل {month} أولاً (تبويب إقفال الدفاتر)، حتى لا تتغير أرقامه بعد تقديم الإقرار.',
  'A later month is already settled.': 'تمت تسوية شهر لاحق بالفعل.',
  'Withholding tax (Form 41)': 'ضريبة الخصم والإضافة (نموذج ٤١)',
  'Quarter': 'الربع',
  'Q{q} {year}': 'الربع {q} {year}',
  'Choose the withholding rate when you register a payment. What you keep back from suppliers is owed to the Tax Authority (account 2400) and goes on Form 41; what customers deduct from you is a claim (account 1450), to match against the certificates they send.': 'اختر نسبة الخصم عند تسجيل الدفعة. ما تستقطعه من الموردين مستحق لمصلحة الضرائب (حساب ٢٤٠٠) ويُدرج في نموذج ٤١؛ وما يخصمه العملاء منك يُعد مطالبة (حساب ١٤٥٠) تُطابق مع الشهادات التي يرسلونها.',
