  'Critical actions wait for a manager’s sign-off, like Odoo approvals. The approver gets a notification. An approval stops counting if the record changes afterwards, and people can’t approve their own requests.': 'الإجراءات المهمة تنتظر اعتماد المدير، مثل موافقات Odoo. يصل للمعتمد إشعار. تسقط الموافقة إذا تغير السجل بعدها، ولا يمكن لأحد اعتماد طلبه بنفسه.',
