  'Column {n}': 'العمود {n}',
  'Old .xls files can’t be read. In Excel, choose File → Save as → Excel workbook (.xlsx) or CSV.': 'ملفات ‎.xls القديمة لا يمكن قراءتها. في إكسل اختر ملف ← حفظ باسم ← مصنف إكسل (‎.xlsx) أو CSV.',
  'This file has no rows': 'هذا الملف لا يحتوي على صفوف',
  'Import up to {n} rows from one file. Split the file and import it in parts.': 'استورد حتى {n} صف من ملف واحد. قسّم الملف واستورده على أجزاء.',
