  'Upload an Excel workbook (.xlsx) or a CSV file. The first row must be the column names. Nothing is saved until you have checked the rows, and a whole import can be undone afterwards.': 'ارفع ملف إكسل (‎.xlsx) أو ملف CSV. يجب أن يحتوي الصف الأول على أسماء الأعمدة. لا يُحفظ شيء قبل أن تفحص الصفوف، ويمكن التراجع عن الاستيراد كاملًا بعد ذلك.',
