  'Only update; don’t add new records': 'حدّث فقط؛ لا تضف سجلات جديدة',
  'Choose a column such as the old system id, phone or e-mail, so importing the same people again updates them instead of adding them twice.': 'اختر عمودًا مثل المعرّف في النظام القديم أو الهاتف أو البريد الإلكتروني، حتى يؤدي استيراد نفس الأشخاص مرة أخرى إلى تحديثهم بدلًا من إضافتهم مرتين.',
  'Values to match ({n})': 'قيم تحتاج إلى مطابقة ({n})',
  'These values in your file are not options here. Choose what each one means, or leave it empty.': 'هذه القيم في ملفك ليست من الخيارات هنا. اختر ما تعنيه كل قيمة، أو اتركها فارغة.',
