  '{n} with problems': '{n} به مشكلات',
  '{n} new rows look like records already in Nasq360 (same name, phone or e-mail). To update those instead of adding them twice, choose a column under “Records already in Nasq360”.': '{n} صفوف جديدة تشبه سجلات موجودة بالفعل في Nasq360 (نفس الاسم أو الهاتف أو البريد). لتحديثها بدلًا من إضافتها مرتين، اختر عمودًا تحت «السجلات الموجودة بالفعل في Nasq360».',
