  'All cost centers': 'كل مراكز التكلفة',
  'Branches, departments, projects or vans. Each income and expense line of an invoice, bill or journal voucher can go to one, so the profit and loss can be read per cost center. A cost center can be under another (a branch and its departments). The balance sheet stays the company’s as a whole.': 'الفروع أو الإدارات أو المشروعات أو سيارات التوزيع. كل بند إيراد أو مصروف في فاتورة بيع أو شراء أو قيد يومية يمكن أن يُحمَّل على مركز تكلفة، فتُقرأ قائمة الدخل لكل مركز. ويمكن أن يتبع مركزٌ مركزًا آخر (فرع وإداراته). أما الميزانية فتبقى للشركة ككل.',
