  'You prepared this budget: another admin approves it, or write why you approve it yourself (at least 10 characters)': 'أنت من أعدّ هذه الموازنة: يعتمدها مسؤول آخر، أو اكتب لماذا تعتمدها بنفسك (10 أحرف على الأقل)',
