  'For': 'لـ',
  'Months gone: what moved through the cash boxes and bank accounts. This month and those to come: invoices and bills by due date (overdue ones now) and cheques by their date. Approve a budget to add what it plans.': 'الشهور الماضية: ما تحرّك في الخزائن والحسابات البنكية. هذا الشهر وما بعده: الفواتير المستحقة بتواريخ استحقاقها (والمتأخرة الآن) والشيكات بتواريخها. اعتمد موازنة لإضافة ما تخطط له.',
  'Months gone: what moved through the cash boxes and bank accounts. This month and those to come: invoices and bills by due date (overdue ones now), cheques by their date, and what the approved budget plans beyond what is already invoiced.': 'الشهور الماضية: ما تحرّك في الخزائن والحسابات البنكية. هذا الشهر وما بعده: الفواتير المستحقة بتواريخ استحقاقها (والمتأخرة الآن)، والشيكات بتواريخها، وما تخطط له الموازنة المعتمدة زيادةً على ما صدرت به فواتير.',
